import React, { useState } from 'react';
import axios from 'axios';
import { useNavigate, Link } from 'react-router-dom';
import './Login.css';

function Login() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const navigate = useNavigate();

  const handleLogin = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    
    try {
      console.log('🔐 Tentative de connexion avec:', { email, password });
      
      const res = await axios.post('http://localhost:5000/api/auth/login', { email, password });
      
      console.log('✅ Réponse complète du serveur:', res.data);
      
      if (res.data.success && res.data.data) {
        const token = res.data.data.token;
        const user = res.data.data.user;
        
        console.log('🔑 Token reçu:', token);
        console.log('👤 User reçu:', user);
        
        // Sauvegarder le token et les infos utilisateur
        localStorage.setItem('token', token);
        localStorage.setItem('user', JSON.stringify(user));
        
        // Redirection basée sur le rôle
        if (user.role === 'student') {
          console.log('🎓 Redirection vers dashboard étudiant');
          navigate('/dashboard-student');
        } else if (user.role === 'prof') {
          console.log('👨‍🏫 Redirection vers dashboard prof');
          navigate('/dashboard-prof');
        } else {
          console.log('❌ Rôle non reconnu:', user.role);
          alert('Rôle utilisateur non reconnu');
        }
      } else {
        console.log('❌ Structure de réponse incorrecte');
        alert(res.data.message || 'Erreur de connexion');
      }
      
    } catch (err) {
      console.error('💥 Erreur de connexion:', err);
      console.log('📡 Données erreur:', err.response?.data);
      
      const errorMessage = err.response?.data?.message || 
                          err.response?.data?.msg || 
                          'Email ou mot de passe incorrect';
      
      alert(errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="login-container">
      <div className="login-card">
        <div className="login-header">
          <div className="logo">
            <i className="fas fa-graduation-cap"></i>
            <span>Gestion Cours</span>
          </div>
          <h2>Content de vous revoir</h2>
          <p>Connectez-vous à votre compte</p>
        </div>

        <form onSubmit={handleLogin} className="login-form">
          <div className="form-group">
            <label htmlFor="email">Adresse email</label>
            <input 
              id="email"
              type="email" 
              placeholder="exemple@email.com" 
              value={email} 
              onChange={e => setEmail(e.target.value)} 
              required 
              className="form-input"
            />
          </div>

          <div className="form-group">
            <div className="password-label-container">
              <label htmlFor="password">Mot de passe</label>
              <Link to="/forgot-password" className="forgot-password">
                Mot de passe oublié ?
              </Link>
            </div>
            <input 
              id="password"
              type="password" 
              placeholder="Votre mot de passe" 
              value={password} 
              onChange={e => setPassword(e.target.value)} 
              required 
              className="form-input"
            />
          </div>

          <button 
            type="submit" 
            className={`submit-btn ${isLoading ? 'loading' : ''}`}
            disabled={isLoading}
          >
            {isLoading ? (
              <>
                <span className="spinner"></span>
                Connexion en cours...
              </>
            ) : (
              'Se connecter'
            )}
          </button>
        </form>

        <div className="login-footer">
          <div className="separator">
            <span>Nouveau sur la plateforme ?</span>
          </div>
          <Link to="/register" className="register-link">
            Créer un compte
          </Link>
        </div>

        <div className="demo-accounts">
          <details className="demo-section">
            <summary>Comptes de démonstration</summary>
            <div className="demo-cards">
              <div className="demo-card">
                <h4>👨‍🎓 Étudiant</h4>
                <p><strong>Email:</strong> etudiant@demo.com</p>
                <p><strong>Mot de passe:</strong> 123456</p>
              </div>
              <div className="demo-card">
                <h4>👨‍🏫 Professeur</h4>
                <p><strong>Email:</strong> prof@demo.com</p>
                <p><strong>Mot de passe:</strong> 123456</p>
              </div>
            </div>
          </details>
        </div>
      </div>
    </div>
  );
}

export default Login;
